package com.tencent.weknora.storage;
import com.fasterxml.jackson.databind.*;
import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.transaction.support.TransactionTemplate;
import static org.assertj.core.api.Assertions.*;

/** Old SQLite schema plus real filesystem: authorization, shared lifetime and compensating rollback. */
class ResourceCatalogTest {
    @TempDir Path temporary;JdbcTemplate jdbc;DataSourceTransactionManager manager;ResourceCatalog catalog;MutableClock clock;ResourceFileStore files;LocalFileStore physical;
    @BeforeEach void initialize()throws Exception{var source=new DriverManagerDataSource("jdbc:sqlite:"+temporary.resolve("registry.db"));source.setDriverClassName("org.sqlite.JDBC");jdbc=new JdbcTemplate(source);manager=new DataSourceTransactionManager(source);try(var connection=source.getConnection()){ScriptUtils.executeSqlScript(connection,new FileSystemResource("../migrations/sqlite/000000_init.up.sql"));}clock=new MutableClock();catalog=new ResourceCatalog(jdbc,new FileUrlSigner(StorageGoCompatibilityTest.KEY,"",clock),clock);physical=new LocalFileStore(temporary.resolve("files"),"",null,1024);files=new ResourceFileStore(physical,catalog,1,"https://files.test");}
    String register(){return catalog.register(1,"storage://instance/local://1/exports/a.txt",ResourceCatalog.Registration.file("a.txt",3));}
    @Test void locationDedupAndTenantScopesDoNotLeakPhysicalPaths()throws Exception{String ref=register();assertThat(register()).isEqualTo(ref);var resource=catalog.resolve(1,ref);assertThat(resource.storageBackendId()).isEqualTo("instance");assertThat(resource.provider()).isEqualTo("local");assertThat(resource.physicalPath()).contains("local://1/");assertThatThrownBy(()->catalog.resolve(2,ref)).isInstanceOf(NoSuchElementException.class);assertThatThrownBy(()->catalog.register(2,ref,ResourceCatalog.Registration.file("",0))).isInstanceOf(NoSuchElementException.class);var mapper=new ObjectMapper().findAndRegisterModules();JsonNode dto=mapper.valueToTree(resource);assertThat(dto.has("physical_path")).isFalse();assertThat(dto.has("location_hash")).isFalse();assertThat(dto.path("deleted_at").isNull()).isTrue();assertThat(dto.path("tenant_id").asInt()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resources",Long.class)).isEqualTo(1);}
    @Test void bindingDeduplicatesAndReleasePreservesOtherOwnerClaims(){String ref=register();catalog.bind(1,ref,"knowledge","doc1","source_file");catalog.bind(1,ref,"knowledge","doc1","source_file");catalog.bind(1,ref,"knowledge","doc1","extracted_image");catalog.bind(1,ref,"message","message1","artifact");assertThat(catalog.release(1,ref,"knowledge","doc1")).isEqualTo(1);assertThat(catalog.release(1,ref,"knowledge","doc1")).isEqualTo(1);assertThat(catalog.release(1,ref,"message","message1")).isZero();assertThat(catalog.release(1,"local://1/a","knowledge","doc1")).isEqualTo(-1);assertThatThrownBy(()->catalog.bind(2,ref,"knowledge","doc","source_file")).isInstanceOf(NoSuchElementException.class);}
    @Test void deterministicGrantReusesHashOnlyAndRevocationCannotReviveSameToken(){String ref=register(),token=catalog.createGrant(1,ref,Duration.ofHours(2));assertThat(catalog.createGrant(1,ref,Duration.ofHours(2))).isEqualTo(token);var grant=jdbc.queryForMap("SELECT * FROM resource_access_grants");assertThat(grant.get("token_hash")).isEqualTo(ResourceCatalog.hash(token));assertThat(grant.toString()).doesNotContain(token);assertThat(catalog.resolveGrant(token).reference()).isEqualTo(ref);assertThat(catalog.revokeGrant(token)).isTrue();assertThatThrownBy(()->catalog.resolveGrant(token)).isInstanceOf(NoSuchElementException.class);String next=catalog.createGrant(1,ref,Duration.ofHours(2));assertThat(next).isNotEqualTo(token);assertThat(catalog.resolveGrant(next).reference()).isEqualTo(ref);assertThatThrownBy(()->catalog.resolveGrant(token)).isInstanceOf(NoSuchElementException.class);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resource_access_grants",Long.class)).isEqualTo(2);}
    @Test void differentTtlWindowsWithSameUnixSecondReuseExistingGoGrant(){clock.now=Instant.parse("2026-10-13T01:02:19.750Z");String ref=register(),first=catalog.createGrant(1,ref,Duration.ofSeconds(17));String originalExpiry=jdbc.queryForObject("SELECT expires_at FROM resource_access_grants",String.class);assertThat(catalog.createGrant(1,ref,Duration.ofMillis(13))).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resource_access_grants",Long.class)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT expires_at FROM resource_access_grants",String.class)).isEqualTo(originalExpiry);clock.advance(Duration.ofMillis(20));assertThat(catalog.resolveGrant(first).reference()).isEqualTo(ref);}
    @Test void grantsExpireStrictlyAndDeletedResourcesNeverResolve(){String ref=register(),token=catalog.createGrant(1,ref,Duration.ofSeconds(4));clock.advance(Duration.ofSeconds(4));assertThatThrownBy(()->catalog.resolveGrant(token)).isInstanceOf(NoSuchElementException.class);String active=catalog.createGrant(1,ref,Duration.ofHours(2));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resource_access_grants",Long.class)).isEqualTo(1);catalog.markDeleted(1,ref);assertThatThrownBy(()->catalog.resolve(1,ref)).isInstanceOf(NoSuchElementException.class);assertThatThrownBy(()->catalog.resolveGrant(active)).isInstanceOf(NoSuchElementException.class);String replacement=register();assertThat(replacement).isNotEqualTo(ref);}
    @Test void missingSigningKeyMakesRandomGrantsWithStoredRevocation(){var randomCatalog=new ResourceCatalog(jdbc,new FileUrlSigner("","",clock),clock);String ref=register(),a=randomCatalog.createGrant(1,ref,Duration.ZERO),b=randomCatalog.createGrant(1,ref,Duration.ZERO);assertThat(a).isNotEqualTo(b);assertThat(randomCatalog.resolveGrant(a).reference()).isEqualTo(ref);randomCatalog.revokeGrant(a);assertThatThrownBy(()->randomCatalog.resolveGrant(a)).isInstanceOf(NoSuchElementException.class);}
    @Test void authoritativeKnowledgeAndExactMessageArtifactBindingsControlScope(){String ref=register();jdbc.update("INSERT INTO knowledge_bases(id,name,tenant_id,embedding_model_id,summary_model_id) VALUES('kb','kb',1,'','')");jdbc.update("INSERT INTO knowledges(id,tenant_id,knowledge_base_id,type,title,source) VALUES('doc',1,'kb','file','doc','upload')");catalog.bind(1,ref,"knowledge","doc","source_file");catalog.bind(1,ref,"message","m1","attachment");assertThat(catalog.referencedByKnowledgeBase(1,"kb",ref)).isTrue();assertThat(catalog.referencedByKnowledgeBase(1,"foreign",ref)).isFalse();assertThat(catalog.messageBindings(1,ref,"m1").knowledgeBaseIds()).containsExactly("kb");assertThat(catalog.messageBindings(1,ref,"m1").messageArtifact()).isFalse();catalog.bind(1,ref,"message","m1","artifact");assertThat(catalog.messageBindings(1,ref,"m1").messageArtifact()).isTrue();assertThat(catalog.messageBindings(1,ref,"m2").messageArtifact()).isFalse();jdbc.update("UPDATE knowledges SET deleted_at=CURRENT_TIMESTAMP WHERE id='doc'");assertThat(catalog.referencedByKnowledgeBase(1,"kb",ref)).isFalse();assertThat(catalog.messageBindings(1,ref,"m1").knowledgeBaseIds()).isEmpty();}
    @Test void decoratorSavesMetadataGrantsAndIndependentCopyThenDeletion()throws Exception{String ref=files.saveFile(new ByteArrayInputStream(new byte[]{1,2,3}),"image.png",1,"doc");var resource=catalog.resolve(1,ref);assertThat(resource.kind()).isEqualTo("image");assertThat(resource.size()).isEqualTo(3);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resource_bindings",Long.class)).isEqualTo(1);String copied=files.copy(ref,1,"doc2");String url=files.url(ref);assertThat(url).startsWith("https://files.test/r/");assertThat(catalog.resolveGrant(url.substring(url.lastIndexOf('/')+1)).reference()).isEqualTo(ref);assertThat(catalog.release(1,ref,"knowledge","doc")).isZero();files.delete(ref);try(var stream=files.open(copied)){assertThat(stream.readAllBytes()).containsExactly(1,2,3);}assertThatThrownBy(()->files.open(ref)).isInstanceOf(IOException.class);assertThatThrownBy(()->files.open("local://2/exports/a")).isInstanceOf(IOException.class);assertThatThrownBy(()->files.saveBytes(new byte[]{1},2,"a",false)).isInstanceOf(IOException.class);}
    @Test void temporaryBytesHashOriginalNameAndLifecycleArePersisted()throws Exception{byte[] bytes="hello".getBytes();String ref=files.saveBytes(bytes,1,"nested/note.txt",true);var resource=catalog.resolve(1,ref);assertThat(resource.originalName()).isEqualTo("note.txt");assertThat(resource.size()).isEqualTo(bytes.length);assertThat(resource.contentHash()).isEqualTo(ResourceCatalog.hashBytes(bytes));assertThat(resource.lifecycle()).isEqualTo("temporary");}
    @Test void businessRollbackRemovesPhysicalObjectsAndRegistryRows(){assertThatThrownBy(()->new TransactionTemplate(manager).executeWithoutResult(status->{try{files.saveFile(new ByteArrayInputStream(new byte[]{1}),"a.txt",1,"doc");}catch(IOException ex){throw new UncheckedIOException(ex);}throw new IllegalStateException("rollback");})).isInstanceOf(IllegalStateException.class);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resources",Long.class)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resource_bindings",Long.class)).isZero();try(var walk=Files.walk(temporary.resolve("files"))){assertThat(walk.filter(Files::isRegularFile)).isEmpty();}catch(IOException ex){throw new UncheckedIOException(ex);}}
    @Test void failedRegistrationAndBindingCompensateCreatedBytes()throws Exception{jdbc.execute("DROP TABLE resource_bindings");assertThatThrownBy(()->files.saveFile(new ByteArrayInputStream(new byte[]{1}),"a.txt",1,"doc")).isInstanceOf(IOException.class).hasMessageContaining("bind");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resources WHERE deleted_at IS NULL",Long.class)).isZero();jdbc.execute("DROP TABLE resources");assertThatThrownBy(()->files.saveBytes(new byte[]{1},1,"a",false)).isInstanceOf(IOException.class).hasMessageContaining("register");try(var walk=Files.walk(temporary.resolve("files"))){assertThat(walk.filter(Files::isRegularFile)).isEmpty();}}
    @Test void persistedUploadMimeAndKindsMatchActualGoRegistrations()throws Exception{Set<String> names=Set.of("document.csv","document.txt","document.js","document.ico","document.json","document.wav","document.docx","document.xlsx","文档.PNG","图.unknown");int matched=0;for(var row:StorageMimeCompatibilityTest.oracle().path("rows")){String name=row.path("name").asText();if(!names.contains(name))continue;String ref=files.saveBytes(new byte[]{1,2,3},1,name,false);var resource=catalog.resolve(1,ref);assertThat(resource.mimeType()).as(name).isEqualTo(row.path("mime").asText());assertThat(resource.kind()).as(name).isEqualTo(row.path("kind").asText());assertThat(resource.originalName()).as(name).isEqualTo(row.path("original_name").asText());matched++;}assertThat(matched).isEqualTo(names.size());assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resources",Long.class)).isEqualTo((long)names.size());}
    static final class MutableClock extends Clock {Instant now=Instant.parse("2026-10-13T00:00:00Z");void advance(Duration duration){now=now.plus(duration);}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return now;}}
}
